import {LETTER_TEMPLATES,TYPE_LABELS} from './letters-core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(id,label,value='',area=false)=>`<label class="field"><span>${esc(label)}</span>${area?`<textarea id="${id}" rows="5">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}">`}</label>`;
function show(env,title,body,footer){env.modal(title,body+'<div id="management-error" class="error-msg" role="alert"></div>',footer,true)}
function bindSave(id,fn){$(id).onclick=async()=>{const button=$(id);button.disabled=true;try{await fn()}catch(e){$('#management-error').textContent=e.message}finally{button.disabled=false}}}
export async function templateManager(env,api){
 const resources=await api('/api/v1/letter-resources');
 show(env,'管理函件模板',`<p>新增或修改后形成新版本，新任务使用当前有效版本；历史任务保留原模板快照。模板版式和适用范围仍需业务方确认。</p><div class="letter-admin-table"><table><thead><tr><th>模板</th><th>类型 / 版本</th><th>状态</th><th>操作</th></tr></thead><tbody>${resources.templates.map((t,i)=>`<tr><td><b>${esc(t.name)}</b><small>${esc(t.source)}</small></td><td>${esc(TYPE_LABELS[t.type])}<br>v${esc(t.version)}</td><td>${t.enabled?'启用':'已停用'}</td><td><button id="tpl-edit-${i}" class="small">修改</button> <button id="tpl-toggle-${i}" class="small">${t.enabled?'停用':'启用'}</button><details><summary>历史 ${t.history?.length||0} 版</summary>${(t.history||[]).map(h=>`<p>v${esc(h.version)} · ${esc(h.name)} · ${h.enabled?'启用':'停用'}<br>${esc(h.updatedBy||'初始模板')} ${esc(h.updatedAt||'')}</p>`).join('')}</details></td></tr>`).join('')}</tbody></table></div>`, '<button data-action="close">关闭</button><button id="tpl-new" class="primary">新增模板</button>');
 $('#tpl-new').onclick=()=>templateForm(env,api,resources,null);
 resources.templates.forEach((t,i)=>{
  $('#tpl-edit-'+i).onclick=()=>templateForm(env,api,resources,t);
  $('#tpl-toggle-'+i).onclick=()=>{show(env,(t.enabled?'停用':'启用')+'模板',`<p>${esc(t.name)} v${esc(t.version)}。变更影响新任务，历史任务仍保留原版本。</p>${field('tpl-actor','维护人员')}`,'<button data-action="close">取消</button><button id="tpl-apply" class="primary">保存状态</button>');bindSave('#tpl-apply',async()=>{await api('/api/v1/letter-resources',{action:'set-template-enabled',expectedRevision:resources.revision,id:t.id,enabled:!t.enabled,actor:$('#tpl-actor').value});await templateManager(env,api)})};
 });
}
function templateForm(env,api,resources,original,type=original?.type||'general'){
 const base=resources.templates.find(t=>t.id===type)||LETTER_TEMPLATES.find(t=>t.id===type),t=original||{...base,name:base.name+'（新模板）'};
 const body=t.bodyBlocks||['{{projectOverview}}','{{routeSummary}}','{{specialFacts}}','{{historySummary}}','现就{{requestItems}}征询贵单位意见，请予指导。'];
 show(env,original?'修改模板 · '+t.name:'新增协议模板',`<p>每段之间空一行。事实使用下列占位符，参数和附件由程序装配：<code>{{projectOverview}} {{routeSummary}} {{requestItems}} {{specialFacts}} {{historySummary}}</code>。前三项必须保留，不直接写入工程数值或审批结论。</p><label class="field"><span>协议类型</span><select id="tpl-type" ${original?'disabled':''}>${LETTER_TEMPLATES.map(b=>`<option value="${b.id}" ${type===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${field('tpl-name','模板名称',t.name)}${field('tpl-source','模板来源 / 业务确认依据',t.source)}${field('tpl-purpose','适用说明',t.purpose)}${field('tpl-units','适用单位编号（逗号分隔；留空为该协议类型通用）',(t.unitIds||[]).join(','))}${field('tpl-body','正文结构',body.join('\n\n'),true)}${field('tpl-attachments','必需附件类型（每行一个）',t.attachments.join('\n'),true)}<details><summary>必填参数配置</summary><p class="muted">使用字段名和显示名称的二元数组，保留当前类型基础参数。</p>${field('tpl-required','参数配置 JSON',JSON.stringify(t.required,null,2),true)}</details>${field('tpl-actor','维护人员')}`,'<button data-action="close">取消</button><button id="tpl-save" class="primary">保存为新版本</button>');
 if(!original)$('#tpl-type').onchange=()=>templateForm(env,api,resources,null,$('#tpl-type').value);
 bindSave('#tpl-save',async()=>{await api('/api/v1/letter-resources',{action:'save-template',id:original?.id,expectedRevision:resources.revision,actor:$('#tpl-actor').value,template:{type,unitIds:$('#tpl-units').value.split(/[,，\n]/).map(v=>v.trim()).filter(Boolean),name:$('#tpl-name').value,source:$('#tpl-source').value,purpose:$('#tpl-purpose').value,bodyBlocks:$('#tpl-body').value.split(/\n\s*\n/).filter(v=>v.trim()),attachments:$('#tpl-attachments').value.split(/\n/).map(v=>v.trim()).filter(Boolean),required:JSON.parse($('#tpl-required').value)}});await templateManager(env,api)});
}
export async function directoryManager(env,api,input){
 const resources=await api('/api/v1/letter-resources');
 show(env,'管理单位资料',`<div class="directory-manager"><p>导入平台或业务方提供的结构化资料，系统按对象编号或“区划＋协议类型＋关系”匹配候选；不从地图或照片推断权属。JSON导入替换同类整批资料，已有函件仍保留原匹配依据。</p><div class="directory-stats"><span>单位目录 ${resources.authorities.length} 条</span><span>区划 ${resources.areas.length} 条</span><span>空间关系 ${resources.relations.length} 条</span></div><div class="directory-actions"><button id="directory-authorities">导入单位与区划目录</button><button id="directory-relations">导入空间关系</button><button id="directory-sample">下载格式示例</button></div><details class="directory-records"><summary>查看当前资料与维护记录</summary><pre class="codebox">${esc(JSON.stringify(resources,null,2))}</pre></details></div>`,'<button data-action="close">关闭</button>');
 $('#directory-authorities').onclick=()=>importResource(env,api,input,resources,'directory');$('#directory-relations').onclick=()=>importResource(env,api,input,resources,'relations');
 $('#directory-sample').onclick=()=>env.download('收函单位与空间关系_格式示例.json',JSON.stringify({说明:'以下均为模拟格式示例。请替换为平台和业务方确认的数据；示例不会自动导入。',directory:{areas:[{code:'SIM-AREA',name:'模拟行政区域',source:'模拟来源，须替换正式资料'}],authorities:[{id:'SIM-UNIT',unit:'模拟收函单位',areaCodes:['SIM-AREA'],featureIds:[],types:['general'],relationTypes:['涉及'],basis:'模拟管理归属依据，须由业务确认',role:'主管/管理或权属角色',enabled:true}]},relations:[{id:'SIM-REL',projectId:input.project.id,routeId:input.route.id,routeVersion:input.project.version,segmentId:'SIM-SEG',scope:'模拟T001—T002区段',featureId:'SIM-FEATURE',featureName:'模拟对象',relationType:'涉及',type:'general',areaCodes:['SIM-AREA'],points:'需业务确认的征询事项',evidence:'模拟空间关系与触发依据，须替换正式资料',reviewed:false}]},null,2),'application/json');
}
function importResource(env,api,input,resources,kind){
 const directory=kind==='directory',value=directory?{areas:resources.areas,authorities:resources.authorities}:{relations:resources.relations};
 show(env,directory?'导入收函单位与区划目录':'导入线路空间关系',`<p>请粘贴JSON或选择文件，保存将替换当前同类资料；目录记录必须包含管理依据，空间关系须关联工程、路径版本、区段和对象。维护记录保存在后端。</p>${field('directory-json','资料 JSON',JSON.stringify(value,null,2),true)}<label class="field"><span>或选择JSON文件（最多2MB）</span><input id="directory-file" type="file" accept=".json"></label>${field('directory-actor','资料维护人员')}`,'<button data-action="close">取消</button><button id="directory-save" class="primary">校验并保存资料</button>');
 bindSave('#directory-save',async()=>{const file=$('#directory-file').files?.[0];if(file?.size>2*1024*1024)throw new Error('JSON文件不能超过2MB');const v=JSON.parse(file?await file.text():$('#directory-json').value);await api('/api/v1/letter-resources',{action:directory?'import-directory':'import-relations',expectedRevision:resources.revision,actor:$('#directory-actor').value,...(directory?{areas:v.areas,authorities:v.authorities}:{relations:v.relations})});await directoryManager(env,api,input)});
}
export async function recipientRecommendations(env,api,input,onApply){
 const result=await api('/api/v1/letter-resources',{action:'recommend',lettersInput:input});
 const candidates=[];for(const item of result.items)for(const candidate of item.candidates)candidates.push({relation:item.relation,candidate,status:item.status});
 show(env,'匹配征询单位',`<p>按已导入的线路关系和单位目录生成匹配结果。勾选需要发函的单位，核对区段、事项和管理依据后加入协议清单。</p>${result.excludedVersionCount?`<div class="notice">已排除 ${result.excludedVersionCount} 条路径版本不一致的空间关系。</div>`:''}${!result.items.length?'<div class="notice">当前工程、路径及版本暂无空间关系，无法匹配。请先从“更多操作 → 管理单位资料”导入资料。</div>':''}${result.items.map(item=>`<div class="checkcard"><b>${esc(item.relation.scope)} · ${esc(item.relation.featureName)}</b><p>${esc(item.relation.relationType)} · ${esc(TYPE_LABELS[item.relation.type])} · ${esc(item.status)}</p><p>事项：${esc(item.relation.points)}<br>来源：${esc(item.relation.evidence)}</p>${item.candidates.length?item.candidates.map(c=>{const i=candidates.findIndex(x=>x.relation.id===item.relation.id&&x.candidate.authorityId===c.authorityId);return `<label class="checklabel"><input id="candidate-${i}" type="checkbox"><span><b>${esc(c.unit)}</b> · ${esc(c.role)}<br>匹配：${esc(c.matchBy)}<br>依据：${esc(c.basis)}</span></label>`}).join(''):'<p class="error-msg">缺少有效单位映射，请补充目录或手工填写经确认的协议事项。</p>'}</div>`).join('')}${candidates.length?`${field('recipient-reviewer','清单确认人员')}<label class="checklabel"><input id="recipient-check" type="checkbox">我已核对所选单位、空间关系、征询事项及管理归属依据</label>`:''}`,'<button data-action="close">关闭</button>'+(candidates.length?'<button id="recipient-apply" class="primary">确认并加入协议清单</button>':''));
 if(candidates.length)bindSave('#recipient-apply',async()=>{
  const reviewer=$('#recipient-reviewer').value.trim();if(!reviewer||!$('#recipient-check').checked)throw new Error('请填写确认人员并勾选核对项');const chosen=candidates.filter((x,i)=>$('#candidate-'+i).checked);if(!chosen.length)throw new Error('请先勾选确需征询的单位');
  const additions=chosen.filter(x=>!input.agreements.some(a=>a.authorityId===x.candidate.authorityId&&a.recipientEvidence?.relationId===x.relation.id)).map(({relation:r,candidate:c})=>({id:'AGR-'+crypto.randomUUID(),unit:c.unit,type:r.type,scope:r.scope,points:r.points,status:'未发函',round:'first',facts:{},attachments:[],authorityId:c.authorityId,adminAreaCodes:r.areaCodes,featureId:r.featureId,segmentId:r.segmentId,recipientEvidence:{relationId:r.id,relationVersion:r.routeVersion,resourcesRevision:result.revision,evidence:r.evidence,basis:c.basis,upstreamReviewed:r.reviewed,confirmedBy:reviewer,confirmedAt:new Date().toISOString()}}));
  if(!additions.length)throw new Error('所选事项已存在于协议清单，无需重复加入');await onApply(additions);$('#dialog').close();env.render();env.toast('已加入 '+additions.length+' 条经人员确认的协议事项，请补齐参数和实际附件后起草');
 });
}
export function correspondenceForm(env,api,task,letter,onSaved){
 const c=letter.correspondence||{state:'未发出'};
 show(env,'发出与回复记录 · '+letter.unit,`<p>此处只登记实际业务记录，不会发送函件。“已人工复核”与“已发出/已回复”分别保存。登记发出及后续状态前，当前函件版本须已人工复核。</p><label class="field"><span>业务状态</span><select id="ledger-state">${['未发出','已发出待回复','已回复','已闭环'].map(s=>`<option ${s===c.state?'selected':''}>${s}</option>`).join('')}</select></label><div class="field-row">${field('ledger-sent','发出日期 YYYY-MM-DD',c.sentAt)}${field('ledger-replied','回复日期 YYYY-MM-DD',c.replyAt)}</div>${field('ledger-reference','业务文号',c.referenceNumber)}${field('ledger-summary','回复意见摘要',c.replySummary,true)}${field('ledger-closure','闭环处理结果',c.closureNote,true)}${field('ledger-notes','备注',c.notes,true)}${field('ledger-correction','更正原因（状态回退时必填）')}${field('ledger-actor','登记人员')}<details><summary>历史登记 ${letter.correspondenceHistory?.length||0} 条</summary><pre class="codebox">${esc(JSON.stringify(letter.correspondenceHistory||[],null,2))}</pre></details>`,'<button data-action="close">取消</button><button id="ledger-save" class="primary">保存业务记录</button>');
 bindSave('#ledger-save',async()=>{const record={state:$('#ledger-state').value};for(const [k,id] of Object.entries({sentAt:'sent',replyAt:'replied',referenceNumber:'reference',replySummary:'summary',closureNote:'closure',notes:'notes',correctionNote:'correction'}))record[k]=$('#ledger-'+id).value;const t=await api('/api/v1/tasks/'+task.id,{action:'record-correspondence',expectedRevision:task.revision,letterId:letter.id,actor:$('#ledger-actor').value,record});onSaved(t);$('#dialog').close();env.render();env.toast('业务台账已保存，未调用大模型')});
}
